// Des: Pull plain text out of a PDF, no OCR
// Flo: open objects > walk page tree (fallback: all Page objects) > fonts + ToUnicode per page > run content stream operators Tj TJ ' " Td Tm T* > page text > flag when no text layer
// I/O: PDF bytes (caller) > Res (text, pages, needs OCR); typed errors BadPdf Encrypted TooMany Bomb
// ===================================================================
const std = @import("std"); const mem = std.mem; const obje = @import("pa-pdfz-obje.zig"); const cmap = @import("pa-pdfz-cmap.zig");
const CF = .{ .pagz = 3000, .textz = 8 << 20, .depz = 24, .gapz = -200.0, .opsz = 8 };
pub const Res = struct { text: []const u8, pages: u32, ocrz: bool };
const Font = struct { cmp: ?cmap.Cmap = null, cswz: u8 = 1 };
const FNam = struct { name: []const u8, font: *Font };
const Ctx = struct { doc: *obje.Doc, aren: std.mem.Allocator, outp: std.ArrayList(u8) = .empty, pages: u32 = 0, fcache: std.AutoHashMapUnmanaged(u32, *Font) = .empty };
const Tok = struct { numz: f64 = 0, strz: []const u8 = "", kind: u8 = 0 };
const St = struct { y: f64 = 0, lasty: f64 = 0, lead: f64 = 12, have: bool = false, gap: bool = false, font: ?*Font = null };
fn fontLoad(ctx: *Ctx, num: u32) !*Font { if (ctx.fcache.get(num)) |hit| return hit; const fnt = try ctx.aren.create(Font); fnt.* = .{}; try ctx.fcache.put(ctx.aren, num, fnt); const body = ctx.doc.objs.get(num) orelse return fnt; const ps = try obje.dictPairs(ctx.aren, body); if (obje.pairGet(ps, "Subtype")) |sub| { if (mem.find(u8, sub, "Type0") != null) fnt.cswz = 2; } if (obje.pairGet(ps, "ToUnicode")) |tou| { if (obje.refOf(tou)) |tnum| { if (ctx.doc.objs.get(tnum)) |tbod| { if (obje.streamOf(ctx.doc, tbod)) |dec| { if (cmap.cmapParse(ctx.aren, dec)) |cmp| { fnt.cmp = cmp; if (cmp.cswz != 0) fnt.cswz = cmp.cswz; } else |_| {} } else |_| {} } } } return fnt; }
fn resolve(ctx: *Ctx, val: []const u8) []const u8 { if (obje.refOf(val)) |num| return ctx.doc.objs.get(num) orelse ""; return val; }
fn fontsOf(ctx: *Ctx, resv: ?[]const u8, list: *std.ArrayList(FNam)) !void { const res = resolve(ctx, resv orelse return); const rps = try obje.dictPairs(ctx.aren, res); const fdv = resolve(ctx, obje.pairGet(rps, "Font") orelse return); const fps = try obje.dictPairs(ctx.aren, fdv); for (fps) |pair| { const num = obje.refOf(pair.val) orelse continue; try list.append(ctx.aren, .{ .name = pair.key, .font = try fontLoad(ctx, num) }); } }
fn emit(ctx: *Ctx, st: *St, byts: []const u8) !void { if (ctx.outp.items.len > CF.textz) return error.TooMany; if (st.have and @abs(st.y - st.lasty) > 0.5) { try ctx.outp.append(ctx.aren, '\n'); } else if (st.gap and ctx.outp.items.len > 0) { const lst = ctx.outp.items[ctx.outp.items.len - 1]; if (lst != ' ' and lst != '\n') try ctx.outp.append(ctx.aren, ' '); } st.gap = false; st.have = true; st.lasty = st.y; if (st.font) |fnt| { if (fnt.cmp) |cmp| { _ = try cmap.cmapDeco(cmp, ctx.aren, byts, &ctx.outp, fnt.cswz); return; } if (fnt.cswz == 2) return; } for (byts) |chr| { if (chr == '\n' or chr == '\t' or (chr >= 0x20 and chr != 0x7f)) { var buf: [4]u8 = undefined; const lenz = std.unicode.utf8Encode(chr, &buf) catch continue; try ctx.outp.appendSlice(ctx.aren, buf[0..lenz]); } } }
fn litStr(aren: std.mem.Allocator, src: []const u8, from: usize, endp: *usize) ![]const u8 { var outp: std.ArrayList(u8) = .empty; var kix = from + 1; var depz: usize = 1; while (kix < src.len) : (kix += 1) { const chr = src[kix]; if (chr == '\\' and kix + 1 < src.len) { kix += 1; const esc = src[kix]; switch (esc) { 'n' => try outp.append(aren, '\n'), 'r' => try outp.append(aren, '\r'), 't' => try outp.append(aren, '\t'), 'b' => try outp.append(aren, 8), 'f' => try outp.append(aren, 12), '0'...'7' => { var val: u32 = esc - '0'; var cnt: usize = 1; while (cnt < 3 and kix + 1 < src.len and src[kix + 1] >= '0' and src[kix + 1] <= '7') : (cnt += 1) { kix += 1; val = val * 8 + (src[kix] - '0'); } try outp.append(aren, @truncate(val)); }, '\n' => {}, '\r' => { if (kix + 1 < src.len and src[kix + 1] == '\n') kix += 1; }, else => try outp.append(aren, esc) } } else if (chr == '(') { depz += 1; try outp.append(aren, chr); } else if (chr == ')') { depz -= 1; if (depz == 0) { endp.* = kix + 1; return outp.toOwnedSlice(aren); } try outp.append(aren, chr); } else try outp.append(aren, chr); } endp.* = src.len; return outp.toOwnedSlice(aren); }
fn hexStr(aren: std.mem.Allocator, src: []const u8, from: usize, endp: *usize) ![]const u8 { const clo = mem.findScalarPos(u8, src, from, '>') orelse src.len; endp.* = @min(clo + 1, src.len); var outp: std.ArrayList(u8) = .empty; var hi: ?u8 = null; for (src[from + 1 .. clo]) |chr| { const dig = std.fmt.charToDigit(chr, 16) catch continue; if (hi) |hv| { try outp.append(aren, (hv << 4) | dig); hi = null; } else hi = dig; } if (hi) |hv| try outp.append(aren, hv << 4); return outp.toOwnedSlice(aren); }
fn numOf(tok: ?Tok) f64 { if (tok) |tk| return tk.numz; return 0; }
fn contRun(ctx: *Ctx, data: []const u8, fonts: []const FNam) !void { var st: St = .{}; var stk: [CF.opsz]Tok = undefined; var cnt: usize = 0; var kix: usize = 0; while (kix < data.len) { kix = obje.skipWs(data, kix); if (kix >= data.len) break; const chr = data[kix]; var tok: ?Tok = null; if (chr == '(') { var endp: usize = 0; tok = .{ .strz = try litStr(ctx.aren, data, kix, &endp), .kind = 's' }; kix = endp; } else if (chr == '<' and kix + 1 < data.len and data[kix + 1] != '<') { var endp: usize = 0; tok = .{ .strz = try hexStr(ctx.aren, data, kix, &endp), .kind = 's' }; kix = endp; } else if (chr == '<' or chr == '>') { kix = obje.valEnd(data, kix); if (chr == '>') kix = @max(kix, 1); } else if (chr == '[') { const aend = obje.valEnd(data, kix); var arr: std.ArrayList(u8) = .empty; var jix = kix + 1; var sst = St{ .font = st.font, .y = st.y, .lasty = st.y, .have = false }; const mark = ctx.outp.items.len; while (jix < aend - 1) { jix = obje.skipWs(data, jix); if (jix >= aend - 1) break; const cc = data[jix]; if (cc == '(') { var endp: usize = 0; const sval = try litStr(ctx.aren, data, jix, &endp); try emitArr(ctx, &st, sval); jix = endp; } else if (cc == '<') { var endp: usize = 0; const sval = try hexStr(ctx.aren, data, jix, &endp); try emitArr(ctx, &st, sval); jix = endp; } else { var jen = jix; while (jen < aend and !obje.isWs(data[jen]) and !obje.isDel(data[jen])) jen += 1; if (jen == jix) jen = jix + 1; const nval = std.fmt.parseFloat(f64, data[jix..jen]) catch 0; if (nval < CF.gapz) st.gap = true; jix = jen; } } _ = &arr; _ = &sst; _ = mark; kix = aend; tok = .{ .kind = 'a' }; } else if (chr == '/') { const nen = obje.valEnd(data, kix); tok = .{ .strz = data[kix + 1 .. nen], .kind = 'n' }; kix = nen; } else if (std.ascii.isDigit(chr) or chr == '-' or chr == '+' or chr == '.') { var nen = kix + 1; while (nen < data.len and (std.ascii.isDigit(data[nen]) or data[nen] == '.' or data[nen] == '-')) nen += 1; tok = .{ .numz = std.fmt.parseFloat(f64, data[kix..nen]) catch 0, .kind = 'd' }; kix = nen; } else if (chr == ']' or chr == '{' or chr == '}' or chr == ')') { kix += 1; continue; }
if (tok) |tk| { if (cnt == stk.len) { mem.copyForwards(Tok, stk[0 .. stk.len - 1], stk[1..]); cnt -= 1; } stk[cnt] = tk; cnt += 1; continue; }
var oen = kix; while (oen < data.len and !obje.isWs(data[oen]) and !obje.isDel(data[oen])) oen += 1; if (oen == kix) { kix += 1; continue; } const opr = data[kix..oen]; kix = oen; const top: ?Tok = if (cnt > 0) stk[cnt - 1] else null; const sec: ?Tok = if (cnt > 1) stk[cnt - 2] else null;
if (mem.eql(u8, opr, "BT")) { st.y = 0; } else if (mem.eql(u8, opr, "Tf")) { if (sec) |nm| { st.font = null; for (fonts) |fn_| { if (mem.eql(u8, fn_.name, nm.strz)) { st.font = fn_.font; break; } } } } else if (mem.eql(u8, opr, "Tj")) { if (top) |tk| try emit(ctx, &st, tk.strz); } else if (mem.eql(u8, opr, "'") or mem.eql(u8, opr, "\"")) { st.y -= st.lead; if (top) |tk| try emit(ctx, &st, tk.strz); } else if (mem.eql(u8, opr, "Td") or mem.eql(u8, opr, "TD")) { st.y += numOf(top); if (mem.eql(u8, opr, "TD")) st.lead = -numOf(top); if (numOf(sec) != 0) st.gap = true; } else if (mem.eql(u8, opr, "Tm")) { st.y = numOf(top); st.gap = true; } else if (mem.eql(u8, opr, "T*")) { st.y -= st.lead; } else if (mem.eql(u8, opr, "TL")) { st.lead = numOf(top); } else if (mem.eql(u8, opr, "ET")) { st.gap = true; } else if (mem.eql(u8, opr, "BI")) { const eix = mem.findPos(u8, data, kix, "EI") orelse data.len; kix = @min(eix + 2, data.len); }
cnt = 0; } }
fn emitArr(ctx: *Ctx, st: *St, byts: []const u8) !void { try emit(ctx, st, byts); }
fn pageDo(ctx: *Ctx, body: []const u8, inhr: ?[]const u8) !void { const ps = try obje.dictPairs(ctx.aren, body); const resv = obje.pairGet(ps, "Resources") orelse inhr; var fonts: std.ArrayList(FNam) = .empty; try fontsOf(ctx, resv, &fonts); const cv = obje.pairGet(ps, "Contents") orelse return; var refs: std.ArrayList(u32) = .empty; const cbd = resolve(ctx, cv); if (obje.refOf(cv)) |num| { if (mem.startsWith(u8, mem.trimStart(u8, cbd, " \t\r\n"), "[")) { var jix: usize = 0; while (jix < cbd.len) { const nx = obje.skipWs(cbd, jix); if (nx >= cbd.len) break; const ve = obje.valEnd(cbd, nx); if (obje.refOf(cbd[nx..ve])) |rn| try refs.append(ctx.aren, rn); jix = @max(ve, nx + 1); } } else try refs.append(ctx.aren, num); } else { var jix: usize = 0; while (jix < cv.len) { const nx = obje.skipWs(cv, jix); if (nx >= cv.len) break; const ve = obje.valEnd(cv, nx); if (obje.refOf(cv[nx..ve])) |rn| try refs.append(ctx.aren, rn); jix = @max(ve, nx + 1); } } var all: std.ArrayList(u8) = .empty; for (refs.items) |rn| { const sb = ctx.doc.objs.get(rn) orelse continue; const dec = obje.streamOf(ctx.doc, sb) catch continue; try all.appendSlice(ctx.aren, dec); try all.append(ctx.aren, '\n'); } const before = ctx.outp.items.len; try contRun(ctx, all.items, fonts.items); if (ctx.outp.items.len > before) try ctx.outp.appendSlice(ctx.aren, "\n\n"); ctx.pages += 1; }
fn treeWalk(ctx: *Ctx, num: u32, inhr: ?[]const u8, depz: usize, seen: *std.AutoHashMapUnmanaged(u32, void)) !void { if (depz > CF.depz or ctx.pages >= CF.pagz or seen.contains(num)) return; try seen.put(ctx.aren, num, {}); const body = ctx.doc.objs.get(num) orelse return; const ps = try obje.dictPairs(ctx.aren, body); const kids = obje.pairGet(ps, "Kids"); const resv = obje.pairGet(ps, "Resources") orelse inhr; if (kids) |kds| { var jix: usize = 0; while (jix < kds.len) { const nx = obje.skipWs(kds, jix + (if (jix == 0) @as(usize, 1) else 0)); if (nx >= kds.len) break; const ve = obje.valEnd(kds, nx); if (obje.refOf(kds[nx..ve])) |rn| try treeWalk(ctx, rn, resv, depz + 1, seen); jix = @max(ve, nx + 1); } return; } try pageDo(ctx, body, inhr); }
fn rootOf(data: []const u8) ?u32 { var kix: usize = 0; var best: ?u32 = null; while (mem.findPos(u8, data, kix, "/Root")) |hit| { kix = hit + 5; const nx = obje.skipWs(data, kix); const ve = obje.valEnd(data, nx); if (obje.refOf(data[nx..ve])) |rn| best = rn; } return best; }
pub fn pdfText(tmpz: std.mem.Allocator, aren: std.mem.Allocator, data: []const u8) !Res { var doc = try obje.docOpen(aren, tmpz, data); var ctx: Ctx = .{ .doc = &doc, .aren = aren }; var seen: std.AutoHashMapUnmanaged(u32, void) = .empty; if (rootOf(data)) |rn| { if (doc.objs.get(rn)) |cat| { const cps = try obje.dictPairs(aren, cat); if (obje.pairGet(cps, "Pages")) |pgv| { if (obje.refOf(pgv)) |pn| treeWalk(&ctx, pn, null, 0, &seen) catch |err| { if (err == error.TooMany or err == error.OutOfMemory) return err; }; } } } if (ctx.pages == 0) { var nums: std.ArrayList(u32) = .empty; var iter = doc.objs.iterator(); while (iter.next()) |ent| { const bod = ent.value_ptr.*; const ps = obje.dictPairs(aren, bod) catch continue; const typ = obje.pairGet(ps, "Type") orelse continue; if (mem.eql(u8, typ, "/Page")) try nums.append(aren, ent.key_ptr.*); } mem.sort(u32, nums.items, {}, std.sort.asc(u32)); for (nums.items) |nn| { if (ctx.pages >= CF.pagz) break; pageDo(&ctx, doc.objs.get(nn).?, null) catch |err| { if (err == error.TooMany or err == error.OutOfMemory) return err; }; } } const text = mem.trim(u8, ctx.outp.items, " \t\r\n"); return .{ .text = text, .pages = ctx.pages, .ocrz = text.len == 0 or (ctx.pages >= 3 and text.len < ctx.pages * 4) }; }
